const loading = false;
const [failed, setFailed] = React.useState(true);
const reload = () => setFailed(false);

<Command>
  <Command.Input placeholder="Search issues…" />
  <Command.List loading={loading}>
    {failed && <Command.Error onRetry={reload}>Couldn’t load issues.</Command.Error>}
    <Command.Empty>No issues match.</Command.Empty>
  </Command.List>
</Command>
